arguments.command:
python3 -c "
import json
f = open('/app/resources/treasury_bulletin_1947_02.json')
data = json.load(f)
def explore(d, depth=0):
    if depth > 4:
        return
    if isinstance(d, dict):
        for k in list(d.keys())[:10]:
            print('  '*depth + str(k))
            explore(d[k], depth+1)
    elif isinstance(d, list):
        print('  '*depth + f'list length: {len(d)}')
explore(data)
"
